import{_ as r}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as a}from"./chunks/ON.DXVlsWbj.js";import{_ as o}from"./chunks/EN.P9aPnFBv.js";import{_ as i}from"./chunks/DIS.DdpTdGGD.js";import{_ as t}from"./chunks/OFF.BrU7kQE-.js";import{_ as l,a as s,b as n,c as d}from"./chunks/M-S-SW-AW-XP24.ELkzeA7z.js";import{_ as c}from"./chunks/M-S-SW-AW-3DM.DGzdotDO.js";import{_ as p,o as m,c as u,a3 as g}from"./chunks/framework.g9mfNVRQ.js";const P=JSON.parse('{"title":"Android Wear","description":"","frontmatter":{"source_hash":"a4207f8d58","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"it/smartwatch/wear.md","filePath":"it/smartwatch/wear.md"}'),h={name:"it/smartwatch/wear.md"};function v(b,e,f,z,_,x){return m(),u("div",null,[...e[0]||(e[0]=[g('<p>Trovi la documentazione di riferimento <a href="https://github.com/NightscoutFoundation/xDrip/blob/master/Documentation/WatchGuide.md" target="_blank" rel="noreferrer">qui</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+r+'" style="zoom:75%;"></p><p> <img src="https://raw.githubusercontent.com/NightscoutFoundation/xDrip/master/app/src/main/res/drawable-xhdpi/ic_watch_grey600_48dp.png" style="width:5%;"> Caratteristiche Collegamenti Smart Watch<br>   Integrazione Android Wear</p></div><p>Dopo aver installato xDrip sull&#39;orologio associato al telefono, puoi attivare Wear.<br> xDrip comunicherà allora con una sua versione ridotta presente sull&#39;orologio.</p><div class="admonition xdripitem"><p class="admonition-title">Integrazione Android Wear <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Inviare dati a Android Watchface Wear.</p></div><p>Con alcune combinazioni di sensore e smartwatch, xDrip può essere usato direttamente dall&#39;orologio, senza bisogno del telefono. Vedi più avanti per maggiori informazioni.</p><p>L&#39;attivazione di Wear permette all&#39;orologio di subentrare al telefono quando xDrip sul telefono perde la connessione con il sensore o il bridge.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita Indossare G5 Collection Service <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p> Collegare indossare per G5 quando il telefono è out-of-range</p></div><p>La forzatura di Wear obbliga l&#39;orologio a fare da dispositivo principale collegato al sensore o al bridge, anche se il telefono è vicino (consigliato).</p><div class="admonition xdripitem"><p class="admonition-title">Forza Indossare servizio G5 Collection <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Telefono Force per l&#39;uso Indossare G5 Collection Service</p></div><p>Disabilita letture da Wear per batteria scarica fa sì che l&#39;orologio lasci la connessione al sensore o al bridge, restituendola al telefono, quando il livello della sua batteria è troppo basso.</p><div class="admonition xdripitem"><p class="admonition-title">Disabilita letture da Wear per batteria scarica <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Disabilita collezione forzata da Wear per allarme batteria smartwatch scarica</p></div><p>Disabilita lettura forzata da smartwatch per assenza letture fa sì che l&#39;orologio lasci la connessione al sensore o al bridge, restituendola al telefono, dopo un certo periodo senza letture, definito nel menu qui sotto.</p><div class="admonition xdripitem"><p class="admonition-title">Disabilita lettura forzata da smartwatch per assenza letture <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p>Disabilita la lettura forzata da Wear dopo minuti di letture mancante dallo smartwatch</p></div><p>Usa solo lo smartwatch può essere attivato se hai configurato l&#39;orologio una volta ma non userai il telefono per collegarti al sensore o al bridge.</p><div class="admonition xdripitem"><p class="admonition-title">Usa solo lo smartwatch <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p>Se pensi di utilizzare solo lo smartwatch in collector e mai il tuo telefono.</p></div><p>Se hai più smartwatch Android Wear con xDrip, puoi scegliere quale farà da collector. Gli altri mostreranno solo i dati di xDrip.</p><div class="admonition xdripitem"><p class="admonition-title">Dispositivo G5 esecuzione Collection Service</p></div><div class="info custom-block"><p class="custom-block-title">Cambio di orologio</p><p>Quando passi da un orologio all&#39;altro, xDrip potrebbe non riuscire a comunicare le sue intenzioni a entrambi se uno è spento. Se vuoi cambiare l&#39;orologio che raccoglie i dati, forza il collector in xDrip e forza il collector anche nel menu xDrip Prefs dell&#39;orologio.</p></div><p>Sincronizza log Wear è una funzione molto utile per la risoluzione problemi: aggiunge i log dell&#39;orologio al <a href="./../use/3dotsmenu.html#events-log">registro eventi</a> di xDrip, con un prefisso che indica che l&#39;attività riguarda l&#39;orologio. Il prefisso predefinito è <code>wear</code>, ma puoi personalizzarlo. Ti consigliamo di lasciarla attiva.</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizza log Wear <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Invia eventi Wear in visualizzazione logs</p></div><p>Visualizzazione Trattamenti aggiunge i simboli dei trattamenti sul grafico dell&#39;orologio.</p><div class="admonition xdripitem"><p class="admonition-title">Visualizzazione Trattamenti <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Visualizzare trattamenti nel grafico</p></div><h2 id="standalone-collector-mode" tabindex="-1">Modalità collector autonomo <a class="header-anchor" href="#standalone-collector-mode" aria-label="Permalink to &quot;Modalità collector autonomo {#standalone-collector-mode}&quot;">​</a></h2><p>L&#39;estensione Wear di xDrip contiene anche la parte di xDrip che si collega ad alcuni sensori: puoi quindi far lavorare l&#39;orologio al posto del telefono e fargli gestire la comunicazione e le letture, senza avere il telefono vicino.</p><p>Questa funzione non è disponibile per tutti i sensori, vedi la tabella qui sotto:</p><table tabindex="0"><thead><tr><th>Sensore</th><th>Wear 1.x</th><th>Wear 2.x</th><th>Wear 3+</th></tr></thead><tbody><tr><td>G5/G6/1</td><td>Sì</td><td>Limitato*</td><td>No</td></tr><tr><td>G7/1+</td><td>No</td><td>No</td><td>No</td></tr><tr><td>Libre 1 con bridge</td><td>Sì</td><td>Sì</td><td></td></tr><tr><td>Libre 14 days US con bridge</td><td>Sì**</td><td>Sì**</td><td></td></tr><tr><td>Libre 2/2+ EU senza bridge</td><td>No</td><td>No</td><td></td></tr><tr><td>Libre 2/2+ EU con bridge</td><td>Sì**</td><td>Sì**</td><td></td></tr></tbody></table><p><em><strong>Limitato*:</strong></em> Sulla maggior parte degli smartwatch Android Wear sono presenti alcuni bug che impediscono il corretto funzionamento con G5/G6. Nel migliore dei casi avrai una lettura ogni 10 minuti. Alcuni orologi possono essere <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">modificati</a> per ottenere letture ogni 5 minuti.</p><div class="info custom-block"><p class="custom-block-title">Perché il mio orologio non riesce a raccogliere da solo i dati di un G5/G6?</p><p>La maggior parte degli orologi Android Wear esce di fabbrica con bug nel firmware Bluetooth che interrompono il ciclo di connessione del G5/G6: l&#39;orologio perde letture o ne riceve solo una ogni 10 minuti. L&#39;unica soluzione trovata è stata modificare il firmware dell&#39;orologio stesso: sbloccare il bootloader e installare una patch tramite una recovery personalizzata. Questo fa decadere la garanzia ed esiste solo per pochi orologi datati (Asus Zenwatch 2/3, Huawei Watch e Watch 2, LG G Watch, Polar M600). La spiegazione completa, l&#39;elenco degli orologi supportati e i &quot;care pack&quot; da scaricare si trovano nella pagina wiki <a href="https://github.com/NightscoutFoundation/xDrip/wiki/Patching-Android-Wear-devices-for-use-with-the-G5" target="_blank" rel="noreferrer">Patching Android Wear devices for use with the G5</a>. Se il tuo orologio non è nell&#39;elenco, non può raccogliere direttamente i dati di un G5/G6: usalo invece come display del telefono.</p></div><p><em><strong>Sì**:</strong></em> Ti serve un telefono funzionante con <a href="./../use/OOP.html">OOP1</a> o <a href="./../use/OOP.html#oop2">OOP2</a> e devi anche <a href="./../troubleshoot/ADB.html#smartwatch">caricare</a> la stessa app OOP sull&#39;orologio. Alcuni bridge potrebbero non essere compatibili.</p><h3 id="prerequisites" tabindex="-1">Prerequisiti <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisiti {#prerequisites}&quot;">​</a></h3><p>La funzione è disponibile per le combinazioni di sensore e orologio descritte sopra.</p><p>L&#39;estensione di xDrip è installata sull&#39;orologio con la stessa versione presente sul telefono.</p><p>La connettività di xDrip sul telefono è buona (cioè i parametri Bluetooth sono impostati correttamente).</p><p>xDrip sull&#39;orologio deve essere autorizzato ad accedere alla posizione.<br><img src="'+l+'" style="zoom:75%;"></p><h3 id="recommended-sequence" tabindex="-1">Sequenza consigliata <a class="header-anchor" href="#recommended-sequence" aria-label="Permalink to &quot;Sequenza consigliata {#recommended-sequence}&quot;">​</a></h3><p>Primo tentativo o ripristino dopo un errore:</p><p>1 - In xDrip sul telefono: disattiva la forzatura del collector, poi la raccolta, poi Wear, in questo ordine.</p><div class="admonition xdripitem"><p class="admonition-title">Forza Indossare servizio G5 Collection <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Abilita Indossare G5 Collection Service <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Integrazione Android Wear <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p></div><p>2 - Attiva i log di Wear.</p><div class="admonition xdripitem"><p class="admonition-title">Sincronizza log Wear <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p><p>Invia eventi Wear in visualizzazione logs</p></div><p>3 - Riavvia lo smartwatch. Aspetta che sia completamente avviato.</p><p>4 - Sul telefono attiva solo Wear.</p><div class="admonition xdripitem"><p class="admonition-title">Integrazione Android Wear <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p></div><p>5 - Aspetta che il grafico di xDrip sia completamente visualizzato sull&#39;orologio (attendere una nuova misurazione non guasta).</p><p>6 - Tieni telefono, orologio e sensore vicini e attiva prima la raccolta, poi la forzatura del collector.</p><div class="admonition xdripitem"><p class="admonition-title">Abilita Indossare G5 Collection Service <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><div class="admonition xdripitem"><p class="admonition-title">Forza Indossare servizio G5 Collection <span class="symbol"><img src="'+o+'" style="zoom:75%;"></span></p></div><p>7 - L&#39;associazione richiede di solito 10 minuti: apri il registro eventi di xDrip sul telefono e aspetta gli eventi che iniziano con <code>wear</code>.<br><img src="'+s+'" style="zoom:75%;"></p><p>8 - Se tutto è andato bene, l&#39;orologio dovrebbe ora essere in modalità autonoma.</p><h5 id="if-the-watch-doesnt-connect-to-the-bridge" tabindex="-1">Se l&#39;orologio non si collega al bridge: <a class="header-anchor" href="#if-the-watch-doesnt-connect-to-the-bridge" aria-label="Permalink to &quot;Se l&#39;orologio non si collega al bridge: {#if-the-watch-doesnt-connect-to-the-bridge}&quot;">​</a></h5><ul><li>Nel menu xDrip Prefs dell&#39;orologio, spunta Force Collector.<br><img src="'+n+'" style="zoom:75%;"></li><li>Dal menu a 3 puntini del quadrante xDrip, scegli Restart Collector.<br><img src="'+c+'" style="zoom:75%;"></li><li>Nelle impostazioni Bluetooth dell&#39;orologio, trova il bridge e fai finta di associarlo (non puoi associare il Miaomiao all&#39;orologio, ma l&#39;orologio proverà a stabilire un collegamento). Dopo il fallimento dell&#39;associazione, aspetta 10 minuti che compaiano le letture.</li><li>Se le letture non compaiono, disattiva Force Collector e ripeti la sequenza.</li></ul><h2 id="sharing-data-in-standalone-mode" tabindex="-1">Condivisione dei dati in modalità autonoma <a class="header-anchor" href="#sharing-data-in-standalone-mode" aria-label="Permalink to &quot;Condivisione dei dati in modalità autonoma {#sharing-data-in-standalone-mode}&quot;">​</a></h2><p>Se vuoi che l&#39;orologio condivida i dati (xDrip Sync, Nightscout, ...), deve essere collegato al telefono e il telefono deve essere connesso a internet.</p><p>Questo non significa che debbano trovarsi nello stesso posto, ma l&#39;orologio non condivide direttamente i dati: li invia al telefono, ed è il telefono a condividerli. Se l&#39;orologio è connesso a internet tramite Wi-Fi o una SIM con piano dati, dovrà inviarli al telefono (anch&#39;esso connesso a internet) e sarà il telefono a condividere i dati. Finché sono entrambi connessi a internet, non serve che siano vicini.</p><img src="'+d+'" style="zoom:75%;"><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Ultima modifica 23/11/2026</em></a></p>',59)])])}const C=p(h,[["render",v]]);export{P as __pageData,C as default};
